function validate([courses]) {
  if (!Array.isArray(courses) || courses.length < 1 || courses.length > 10000) return 'courses needs 1 to 10^4 entries.';
  for (const course of courses) {
    if (!Array.isArray(course) || course.length !== 2) return 'Each course is [duration, lastDay].';
    if (course.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'duration and lastDay are between 1 and 10^4.';
  }
  return null;
}

