function scheduleCourse(courses) {
  // Knapsack over finishing days: in deadline order, best[t] is the most courses that end exactly on day t.
  const sorted = courses.map(c => c.slice()).sort((a, b) => a[1] - b[1]);
  const limit = Math.max(...sorted.map(c => c[1]));
  const best = new Array(limit + 1).fill(-Infinity);
  best[0] = 0;
  for (const [length, deadline] of sorted) {
    for (let t = deadline; t >= length; t--) {
      if (best[t - length] + 1 > best[t]) best[t] = best[t - length] + 1;
    }
  }
  return Math.max(...best);
}

