function generate(rand, size) {
  const pick = m => 1 + Math.floor(rand() * m);
  if (size === 'small') {
    const n = pick(9);
    const maxDuration = pick(10);
    const maxDay = pick(30);
    return [Array.from({ length: n }, () => [pick(maxDuration), pick(maxDay)])];
  }
  const n = 1500 + Math.floor(rand() * 501);
  const style = Math.floor(rand() * 3);
  const courses = Array.from({ length: n }, () => {
    if (style === 0) return [pick(10000), pick(10000)];
    if (style === 1) return [pick(30), pick(10000)];
    return [rand() < 0.1 ? pick(10000) : pick(15), pick(10000)];
  });
  return [courses];
}
